function spellableLength(words: string[], tray: string): number {
  let total = 0;
  for (const w of words) {
    const tiles = tray.split("");
    let ok = true;
    for (const ch of w) {
      const at = tiles.indexOf(ch);
      if (at < 0) { ok = false; break; }
      tiles.splice(at, 1);
    }
    if (ok) total += w.length;
  }
  return total;
}

