class Solution:
    def spellableLength(self, words: List[str], tray: str) -> int:
        total = 0
        for w in words:
            tiles = list(tray)
            ok = True
            for ch in w:
                if ch not in tiles:
                    ok = False
                    break
                tiles.remove(ch)
            if ok:
                total += len(w)
        return total

