function spellableLength(words: string[], tray: string): number {
  const have = new Array(26).fill(0);
  for (const ch of tray) have[ch.charCodeAt(0) - 97]++;
  let total = 0;
  for (const w of words) {
    const need = new Array(26).fill(0);
    let ok = true;
    for (const ch of w) {
      const c = ch.charCodeAt(0) - 97;
      if (++need[c] > have[c]) { ok = false; break; }
    }
    if (ok) total += w.length;
  }
  return total;
}

